/**
 * practice/js/engine/scoring.js
 * Pure scoring and performance evaluation per 04_TEST_ENGINE_SPEC.md §7.
 */

export const MARKING_SCHEMES = {
  neet: { pos: 4, neg: -1, name: 'NEET (+4 / -1)' },
  simple: { pos: 1, neg: 0, name: 'Simple (+1 / 0)' }
};

/**
 * Scores a test attempt.
 * @param {object} params
 * @param {object} params.test Test object generated by generateTest
 * @param {Record<string, number|string>} [params.answers={}] User answers by qid
 * @param {string|object} [params.markingScheme='neet'] 'neet' | 'simple' or { pos, neg }
 * @param {Record<string, number>} [params.selfScores={}] Self-ratings for open questions
 * @param {Record<string, number>} [params.timeMs={}] Time spent per question in ms
 * @param {string[]} [params.hintUsed=[]] Question IDs where hint was viewed
 * @returns {object} Full results report
 */
export function scoreTest(params = {}) {
  // Support both single-object and positional arguments
  const test = params.test || (arguments.length > 0 && typeof arguments[0]?.items === 'object' ? arguments[0] : {});
  const answers = params.answers || arguments[1] || {};
  const markingScheme = params.markingScheme || arguments[2] || test.config?.markingScheme || 'neet';
  const selfScores = params.selfScores || arguments[3] || {};
  const timeMs = params.timeMs || arguments[4] || {};
  const hintUsed = params.hintUsed || arguments[5] || [];

  const items = Array.isArray(test.items) ? test.items : [];

  let scheme = MARKING_SCHEMES.neet;
  if (typeof markingScheme === 'string') {
    scheme = MARKING_SCHEMES[markingScheme.toLowerCase()] || MARKING_SCHEMES.neet;
  } else if (markingScheme && typeof markingScheme.pos === 'number') {
    scheme = markingScheme;
  }
  const pos = scheme.pos;
  const neg = scheme.neg;

  let totalScore = 0;
  let mcqCount = 0;
  let mcqAttempted = 0;
  let mcqCorrect = 0;
  let mcqWrong = 0;
  let mcqSkipped = 0;

  const sectionBuckets = {};
  const topicBuckets = {};
  const evaluatedItems = [];
  const reflectionItems = [];

  for (const item of items) {
    const qid = item.qid || item.id;
    const isMcq = item.type === 'mcq';
    const section = item.section || 'General';
    const topic = item.topic || 'General';

    // Init section bucket
    if (!sectionBuckets[section]) {
      sectionBuckets[section] = {
        section,
        total: 0,
        attempted: 0,
        correct: 0,
        wrong: 0,
        skipped: 0,
        score: 0,
        maxScore: 0,
        accuracy: 0
      };
    }

    // Init topic bucket
    if (!topicBuckets[topic]) {
      topicBuckets[topic] = {
        topic,
        section,
        total: 0,
        attempted: 0,
        correct: 0,
        wrong: 0,
        skipped: 0,
        score: 0,
        maxScore: 0,
        accuracy: 0
      };
    }

    const sBucket = sectionBuckets[section];
    const tBucket = topicBuckets[topic];

    const userAnswer = answers[qid] !== undefined ? answers[qid] : answers[item.id];
    const isAnswered = userAnswer !== undefined && userAnswer !== null && userAnswer !== '';
    const timeSpent = typeof timeMs[qid] === 'number' ? timeMs[qid] : (typeof timeMs[item.id] === 'number' ? timeMs[item.id] : 0);
    const usedHint = Array.isArray(hintUsed) && (hintUsed.includes(qid) || hintUsed.includes(item.id));

    if (isMcq) {
      mcqCount++;
      sBucket.total++;
      tBucket.total++;
      sBucket.maxScore += pos;
      tBucket.maxScore += pos;

      let status = 'skipped';
      let scoreDelta = 0;

      if (!isAnswered) {
        mcqSkipped++;
        sBucket.skipped++;
        tBucket.skipped++;
        status = 'skipped';
        scoreDelta = 0;
      } else {
        mcqAttempted++;
        sBucket.attempted++;
        tBucket.attempted++;

        if (Number(userAnswer) === item.answerIndex) {
          mcqCorrect++;
          sBucket.correct++;
          tBucket.correct++;
          status = 'correct';
          scoreDelta = pos;
        } else {
          mcqWrong++;
          sBucket.wrong++;
          tBucket.wrong++;
          status = 'wrong';
          scoreDelta = neg;
        }
      }

      totalScore += scoreDelta;
      sBucket.score += scoreDelta;
      tBucket.score += scoreDelta;

      evaluatedItems.push({
        qid,
        groupId: item.groupId,
        section,
        topic,
        type: 'mcq',
        prompt: item.prompt,
        options: item.options,
        answerIndex: item.answerIndex,
        userAnswer: isAnswered ? Number(userAnswer) : null,
        status,
        scoreDelta,
        timeMs: timeSpent,
        hintUsed: usedHint,
        rationale: item.rationale,
        hint: item.hint,
        generated: Boolean(item.generated)
      });
    } else {
      // Open / reflective type — never added to score
      const selfScore = selfScores[qid] ?? selfScores[item.id] ?? null;
      const refl = {
        qid,
        groupId: item.groupId,
        section,
        topic,
        type: item.type,
        prompt: item.prompt,
        userResponse: isAnswered ? String(userAnswer) : '',
        rubricMax: item.rubricMax || 3,
        selfScore: selfScore !== null ? Number(selfScore) : null,
        timeMs: timeSpent,
        hintUsed: usedHint,
        rationale: item.rationale,
        hint: item.hint,
        scored: false
      };
      reflectionItems.push(refl);
      evaluatedItems.push(refl);
    }
  }

  // Calculate accuracies
  const maxScore = mcqCount * pos;
  const overallAccuracy = mcqCount > 0 ? (mcqCorrect / mcqCount) : 0;

  for (const s of Object.values(sectionBuckets)) {
    s.accuracy = s.total > 0 ? Math.round((s.correct / s.total) * 1000) / 1000 : 0;
    s.accuracyPercent = Math.round(s.accuracy * 100);
  }

  const topicsToRevise = [];
  for (const t of Object.values(topicBuckets)) {
    t.accuracy = t.total > 0 ? Math.round((t.correct / t.total) * 1000) / 1000 : 0;
    t.accuracyPercent = Math.round(t.accuracy * 100);
    if (t.total > 0 && t.accuracy < 0.60) {
      topicsToRevise.push({
        topic: t.topic,
        section: t.section,
        accuracy: t.accuracy,
        accuracyPercent: t.accuracyPercent,
        correct: t.correct,
        total: t.total
      });
    }
  }

  // Time analysis
  let totalTimeMs = 0;
  let fastestItem = null;
  let slowestItem = null;

  for (const it of evaluatedItems) {
    totalTimeMs += it.timeMs;
    if (it.timeMs > 0) {
      if (!fastestItem || it.timeMs < fastestItem.timeMs) {
        fastestItem = { qid: it.qid, timeMs: it.timeMs, prompt: it.prompt };
      }
      if (!slowestItem || it.timeMs > slowestItem.timeMs) {
        slowestItem = { qid: it.qid, timeMs: it.timeMs, prompt: it.prompt };
      }
    }
  }

  const totalQuestions = items.length;
  const avgTimePerQuestionMs = totalQuestions > 0 ? Math.round(totalTimeMs / totalQuestions) : 0;

  return {
    score: totalScore,
    maxScore,
    scheme: scheme.name,
    totalQuestions,
    mcqCount,
    attempted: mcqAttempted,
    correct: mcqCorrect,
    wrong: mcqWrong,
    skipped: mcqSkipped,
    accuracy: Math.round(overallAccuracy * 1000) / 1000,
    accuracyPercent: Math.round(overallAccuracy * 100),
    bySection: sectionBuckets,
    byTopic: topicBuckets,
    topicsToRevise,
    reflection: reflectionItems,
    items: evaluatedItems,
    timeAnalysis: {
      totalTimeMs,
      avgTimePerQuestionMs,
      fastest: fastestItem,
      slowest: slowestItem,
      hintUsedQids: evaluatedItems.filter(it => it.hintUsed).map(it => it.qid)
    }
  };
}

